const response = $json.choices?.[0]?.message?.content || '{}';
const parsed = JSON.parse(response);
return {
  ...$('Auth + Normalize').first().json,
  vision_producto: parsed.producto || 'no_identificado',
  vision_confianza: parsed.confianza || 0,
  vision_payment_proof: parsed.payment_proof || false,
  vision_razon: parsed.razon || '',
  message_text: `[Imagen recibida: ${parsed.producto} (confianza ${parsed.confianza})]`
};

// Comprobante detectado por el Vision Classifier -> transicion de pago.
// Es lo que en produccion hace WF-04 (Pago Detectado) dentro de GHL.
const ctx = $('Auth + Normalize').first().json;
const currentStage = ctx.stage;
const mediaUrl = ctx.media_url;

// Los ids salen del pipeline resuelto en runtime; el hardcode queda como fallback.
const ids = ctx.stage_ids || {};
const STAGE_IDS = {
  'Esperando Pago':  ids['Esperando Pago']  || '843a06f1-1214-4baa-a3a0-f197cb240b5d',
  'Pago Confirmado': ids['Pago Confirmado'] || '96d760e5-f290-456c-a117-57e61ce6c27d',
};

let nextStageId = null;
let mensaje = '';
let notifyOscar = false;
let comprobanteField = null;

if (currentStage === 'Cotizado') {
  nextStageId = STAGE_IDS['Esperando Pago'];
  mensaje = '¡Recibí tu comprobante! 🎉 Lo verificamos en breve y te confirmamos.';
  comprobanteField = 'anticipo';
} else if (currentStage === 'Esperando Pago') {
  nextStageId = STAGE_IDS['Pago Confirmado'];
  mensaje = '¡Pago confirmado! ✅ Ahora pasamos al diseño de tus recuerditos 🎨';
  notifyOscar = true;
  comprobanteField = 'liquidacion';
} else {
  mensaje = 'Comprobante recibido, un asesor te contactará pronto.';
  comprobanteField = 'anticipo';   // evita que la key se arme como comprobante_null_url
}

return {
  ...ctx,
  nextStageId,
  mensaje,
  notifyOscar,
  currentStage,
  comprobanteField,
  mediaUrl,
};

const row = $json;
const messages = Array.isArray(row.pending_messages) ? row.pending_messages : JSON.parse(row.pending_messages || '[]');
const combinedText = messages.join('\n');

return {
  ...$('Auth + Normalize').first().json,
  message_text: combinedText
};

let text = $json.output || '';

text = text.trim();
if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) {
  text = text.slice(1, -1);
}

// Por si el modelo emite un marcador de imagen: lo borramos. La imagen del evento y las
// fichas las manda el sistema despues de releer el CRM (nodos Check Evento Just Set / Loop Fichas).
text = text.replace(/\[IMAGEN:\s*[^\]]+\]/gi, '');

text = text.replace(/\*\*/g, '*');
text = text.replace(/^#{1,6}\s*/gm, '');

const isCanon = (l) =>
  /⏳|HAZ TU PEDIDO|SENCILLOS PASOS|SEMANA LOCA|DIAS DE PROMO|MUESTRA DIGITAL|PAGO FINAL|FOTO DEL PRODUCTO|COTIZACION de los|ANTICIPO para desarrollar/i.test(l) ||
  /^\s*\d+[.)]\s/.test(l) ||
  /x\s*\$|^\s*(Total|Env[íi]o|Anticipo|Subtotal)\s*[:(]/i.test(l);

text = text.split('\n').filter(l => !/\bkg\b|\bpeso\b|\bkilogramos?\b/i.test(l)).join('\n');
text = text.split('\n').map(l => isCanon(l) ? l : l.replace(/[¿¡]/g, '')).join('\n');

const OFICIAL = '3315948670';
text = text.replace(/\b\d{7,10}\b/g, (m) => (m === OFICIAL ? m : ''));
text = text.replace(/[ \t]{2,}/g, ' ');

// una linea conversacional = una burbuja; los bloques fijos van enteros
const parts = [];
let buf = [], bufCanon = false;
const flush = () => { const s = buf.join('\n').trim(); if (s) parts.push({ message_part: s }); buf = []; };

for (const raw of text.split('\n')) {
  const line = raw.trim();
  if (!line) { flush(); bufCanon = false; continue; }
  if (isCanon(line)) {
    if (!bufCanon) flush();
    buf.push(line); bufCanon = true;
  } else {
    if (bufCanon) { flush(); bufCanon = false; }
    parts.push({ message_part: line });
  }
}
flush();

let out = parts.filter(p => p.message_part);
const MAX = 6;
if (out.length > MAX) {
  out = out.slice(0, MAX - 1).concat([{ message_part: out.slice(MAX - 1).map(p => p.message_part).join('\n') }]);
}
if (!out.length) out = [{ message_part: text.trim() || '...' }];

return out.map(p => ({ message_part: p.message_part, photo_url: '' }));

// Post-agente: relee el Opportunity de GHL y decide que dispara el SISTEMA (no el LLM).
//   1. Evento recien identificado -> imagen principal del evento + promo (paso 2 del flujo original)
//   2. Productos recien mostrados -> fichas de esos productos (las que tengan asset estable)
//   3. Stage a mover              -> lo calcula "Stage Machine" con este mismo output
const ctx  = $('Auth + Normalize').first().json;
const resp = $json || {};
const opp  = resp.opportunity || resp.data || resp || {};

const CF_KEY_BY_ID = {};
for (const [k, v] of Object.entries(ctx.cf_ids || {})) CF_KEY_BY_ID[v] = k;
CF_KEY_BY_ID['ahVpF5ldsRcuOIn9Mxdk'] = CF_KEY_BY_ID['ahVpF5ldsRcuOIn9Mxdk'] || 'evento_detectado';

function cfObject(o) {
  const out = {};
  for (const cf of (o && o.customFields) || []) {
    const key = CF_KEY_BY_ID[cf.id] || String(cf.key || cf.fieldKey || '').replace(/^opportunity\./, '');
    if (!key) continue;
    let v = cf.fieldValue !== undefined ? cf.fieldValue
          : cf.field_value !== undefined ? cf.field_value
          : cf.value;
    if (Array.isArray(v)) v = v[0];
    out[key] = v;
  }
  return out;
}

const antes   = ctx.custom_fields || {};
const despues = cfObject(opp);

// ─────────── 1. imagen principal del evento ───────────
const eventoAntes   = String(antes.evento_detectado || '').trim();
const eventoDespues = String(despues.evento_detectado || '').trim();
const stageAntes = String(ctx.stage || '');
const puedeMandarImagen = ['Lead Nuevo', 'Saludo Enviado'].includes(stageAntes);
const justSet = !eventoAntes && !!eventoDespues && puedeMandarImagen;

const IMAGENES = {
  'Boda': 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/94d1527d-83d1-40e2-bfac-05dd969c3ea7.jpg',
  'XV':   'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/136d7ce1-0487-4767-a408-16742a068939.jpg',
};
const imagenUrl = IMAGENES[eventoDespues] || 'https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/10880c83-56c2-4ee3-b30d-71e910093962.jpg';

const productosBase = 'TENEMOS ESTOS PRODUCTOS PARA TU EVENTO:\n\n*Sandalias*\n*Cilindros*\n';
const mandilLine    = eventoDespues === 'Boda' ? '*Mandiles para Boda*\n' : '';
const descripcion   = `${productosBase}${mandilLine}*Kit anti cruda*\n*Pantuflas*\n\nCuales te interesan?`;
const promoText     = 'Que padre! 😊\n\n🎉 *¡SEMANA LOCA DE PROMOS! SOLO 7 DÍAS PARA LLEVARTE TUS RECUERDITOS PERSONALIZADOS CON DESCUENTAZO* 🎉\n\n*(Pedidos solo para eventos 2026 por tema de tiempos)*';

// ─────────── 2. fichas de producto ───────────
// Assets con URL publica ESTABLE (verificadas 200 OK el 2026-07-24). En Kommo las adjuntaba
// el salesbot por bot_id; al migrar hay que re-hostear cada una. Las que no estan todavia
// NO se envian: el agente las describe en texto y nunca promete la foto.
// Para agregar una: subila a la Media Library de GHL y pega la URL aca.
const FICHAS = {
  'cilindros':     ['https://i.ibb.co/TMNBpPgZ/684359bde4dec.jpg'],
  'kit anticruda': ['https://i.ibb.co/k6vzkZns/68435a4e8ae4e.jpg'],
  'bolsa':         ['https://i.ibb.co/N696v1yV/6843596fd985c.jpg'],
  'tintas':        ['https://i.ibb.co/rRVGZtqL/6843598253827.jpg'],
  'correas 15':    ['https://i.ibb.co/bgGFrHcD/6843598e72a98.jpg'],
  'correas 9':     ['https://i.ibb.co/s9VcrD8n/684359a1847ef.jpg'],
  'tapas termos':  ['https://i.ibb.co/5xBmhSdK/684359acdcdba.jpg'],
  // PENDIENTE de re-hostear (hoy solo viven dentro de los salesbots de Kommo):
  // 'sandalias':   [],   // comparativa de suelas + catalogo PDF + video
  // 'pantuflas':   [],   // ficha + catalogo PDF + video + mono satin + mono peluche
  // 'mandiles':    [],   // infografia + catalogo + video   (solo Boda)
  // 'vaso popote': [],   // ficha unica                     (solo Boda y XV)
};
const ALIAS = {
  'sandalia': 'sandalias', 'sandalias': 'sandalias',
  'sandalia delgada': 'sandalias', 'sandalias delgadas': 'sandalias',
  'sandalia gruesa': 'sandalias', 'sandalias gruesas': 'sandalias',
  'pantufla': 'pantuflas', 'pantuflas': 'pantuflas',
  'pantufla mono': 'pantuflas', 'pantuflas mono': 'pantuflas',
  'pantufla satin': 'pantuflas', 'pantuflas satin': 'pantuflas',
  'cilindro': 'cilindros', 'cilindros': 'cilindros', 'termo': 'cilindros', 'termos': 'cilindros',
  'anticruda': 'kit anticruda', 'anticrudas': 'kit anticruda',
  'kit anticruda': 'kit anticruda', 'kit anticrudas': 'kit anticruda', 'kits anticrudas': 'kit anticruda',
  'mandil': 'mandiles', 'mandiles': 'mandiles',
  'vaso popote': 'vaso popote', 'vasos popote': 'vaso popote', 'vasos': 'vaso popote', 'vaso': 'vaso popote',
  'bolsa': 'bolsa', 'bolsas': 'bolsa', 'shein': 'bolsa',
  'tinta': 'tintas', 'tintas': 'tintas', 'colores': 'tintas',
  'correas 15': 'correas 15', 'correa 15': 'correas 15',
  'correas 9': 'correas 9', 'correa 9': 'correas 9',
  'tapas termos': 'tapas termos', 'tapas': 'tapas termos',
};

const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
const listar = (v) => {
  const s = String(v || '').trim();
  if (!s) return [];
  try { const a = JSON.parse(s); if (Array.isArray(a)) return a.map(norm).filter(Boolean); } catch (e) {}
  return s.split(',').map(norm).filter(Boolean);
};

const prodAntes   = listar(antes.productos_mostrados).map(p => ALIAS[p] || p);
const prodDespues = listar(despues.productos_mostrados).map(p => ALIAS[p] || p);
const nuevos = [...new Set(prodDespues.filter(p => !prodAntes.includes(p)))];

const fichas = [];
for (const p of nuevos) {
  for (const url of (FICHAS[p] || [])) fichas.push({ producto: p, photo_url: url, message_part: '' });
}

// ─────────── 3. atencion humana ───────────
const atencionAntes = (ctx.contact_tags || []).map(t => String(t).toLowerCase()).includes('atencion_humana');

return {
  ...ctx,
  currentEvento: eventoDespues,
  justSet,
  imagenUrl,
  descripcion,
  promoText,
  fichas,
  hayFichas: fichas.length > 0,
  cf_despues: despues,
  stage_actual_crm: (ctx.stage_names && opp.pipelineStageId && ctx.stage_names[opp.pipelineStageId]) || ctx.stage,
  atencion_antes: atencionAntes,
};

const PAUSED_STAGES = ['Esperando Pago', 'Pago Confirmado', 'Diseño en Proceso', 'En Producción', 'Enviado'];
const stage = $('Auth + Normalize').first().json.stage;
const isPausedStage = PAUSED_STAGES.includes(stage);

return {
  ...$json,
  isPausedStage
};

