  "vaso popote": "Vaso Popote 24 oz", "vasos popote": "Vaso Popote 24 oz",
  "vaso popote 24 oz": "Vaso Popote 24 oz", "vasos popote 24 oz": "Vaso Popote 24 oz"
};
const LIMITS = {
  MAX_PER_BOX_WEIGHT_KG: 35, MAX_CILINDROS_PER_BOX: 250,
  MAX_SANDALIAS_PER_BOX: 200, MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX: 200
};

function costoPorPeso(pesoKg) {
  const p = Number(pesoKg.toFixed(2));
  if (p >= 0 && p <= 4.99) return 250;
  if (p >= 5 && p <= 7) return 280;
  if (p > 7 && p <= 12) return 300;
  if (p > 12 && p <= 19.99) return 350;
  if (p >= 19.99 && p <= 35) return 400;
  return 400;
}
function normalizeText(str) {
  return String(str || "").normalize("NFD").replace(/[̀-ͯ]/g, "")
    .toLowerCase().replace(/\s+/g, " ").trim();
}
function canon(raw) {
  const clean = normalizeText(raw);
  if (PRODUCT_ALIASES[clean]) return PRODUCT_ALIASES[clean];
  // Fallback por keyword: tolera las grafías del catálogo del prompt
  // ("Cilindros 500ml", "Vasos popote 24oz", "Sandalias delgadas (suela 9mm)", etc.).
  // Para envío solo importan peso + categoría; igual conservamos la variante si el texto la indica.
  if (clean.includes("cilindro")) return "Cilindros";
  if (clean.includes("vaso")) return "Vaso Popote 24 oz";
  if (clean.includes("mandil")) return "Mandiles";
  if (clean.includes("costal")) return "Costales";
  if (clean.includes("kit") && clean.includes("anticrud")) return "Kits Anticrudas";
  if (clean.includes("bolsa")) return "Bolsa";
  if (clean.includes("pantufla")) {
    if (clean.includes("peluche")) return "Pantufla Moño Peluche";
    if (clean.includes("moño") || clean.includes("mono")) return "Pantufla Moño Satin";
    return "Pantuflas";
  }
  if (clean.includes("sandalia")) {
    if (clean.includes("gruesa") || clean.includes("15mm")) return "Sandalias Gruesas";
    return "Sandalias Delgadas";
  }
  return String(raw || "").trim();
}
function cloneEmptyBoxState() { return { peso: 0, cil: 0, sand: 0, combSC: 0, contenido: {} }; }
function addToBox(box, product, qty, w) {
  box.contenido[product] = (box.contenido[product] || 0) + qty;
  box.peso += qty * w;
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  if (cat === "CILINDROS") { box.cil += qty; box.combSC += qty; }
  else if (cat === "SANDALIAS") { box.sand += qty; box.combSC += qty; }
}
function capacityForProductInBox(box, product, w) {
  const cat = CATEGORY_BY_PRODUCT[product] || "OTROS";
  let cap = Infinity;
  if (w > 0) cap = Math.min(cap, Math.max(0, Math.floor((LIMITS.MAX_PER_BOX_WEIGHT_KG - box.peso) / w)));
  if (cat === "CILINDROS") {
    cap = Math.min(cap, LIMITS.MAX_CILINDROS_PER_BOX - box.cil);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "SANDALIAS") {
    cap = Math.min(cap, LIMITS.MAX_SANDALIAS_PER_BOX - box.sand);
    cap = Math.min(cap, LIMITS.MAX_COMBINED_SANDALIAS_CILINDROS_PER_BOX - box.combSC);
  } else if (cat === "OTROS_0KG") { cap = Infinity; }
  return Math.max(0, cap);
}
function packBoxes(lines) {
  const boxes = [];
  let cur = cloneEmptyBoxState();
  const remaining = {};
  lines.forEach(ln => { remaining[ln.product] = (remaining[ln.product] || 0) + ln.quantity; });
  const hasRemaining = () => Object.keys(remaining).some(k => remaining[k] > 0);
  while (hasRemaining()) {
    let packed = false;
    for (const ln of lines) {
      const need = remaining[ln.product];
      if (!need) continue;
      const cap = capacityForProductInBox(cur, ln.product, ln.weight);
      if (cap <= 0) continue;
      const put = Math.min(need, cap);
      if (put > 0) { addToBox(cur, ln.product, put, ln.weight); remaining[ln.product] -= put; packed = true; }
    }
    if (!packed || !hasRemaining()) {
      if (Object.keys(cur.contenido).length > 0) boxes.push(cur);
      if (hasRemaining()) cur = cloneEmptyBoxState();
    }
  }
  return boxes;
}
function orderFromItems(arr) {
  const acc = {};
  const unknown = [];
  for (const row of arr) {
    const rawProd = String((row && (row.producto ?? row.product)) || "").trim();
    const qty = Number((row && (row.cantidad ?? row.qty)) || 0);
    if (!rawProd || !qty) continue;
    const prod = canon(rawProd);
    const w = WEIGHT_BY_PRODUCT[prod];
    if (typeof w !== "number") { unknown.push(rawProd); continue; }
    if (!acc[prod]) acc[prod] = { product: prod, quantity: 0, weight: w };
    acc[prod].quantity += qty;
  }
  return { lines: Object.values(acc), unknown };
}

// ---- parse input ----
let raw = (typeof query !== "undefined" && query != null) ? query : "";
if (typeof raw === "object") { try { raw = JSON.stringify(raw); } catch (e) { raw = ""; } }
let parsed = null;
try {
  const p = JSON.parse(raw);
  if (Array.isArray(p)) parsed = p;
  else if (p && Array.isArray(p.items)) parsed = p.items;
  else if (p && !Array.isArray(p) && (p.producto || p.product)) parsed = [p]; // objeto único
} catch (e) {}
if (!parsed) {
  parsed = [];
  String(raw).split(/[,;\n]/).forEach(seg => {
    seg = seg.trim(); if (!seg) return;
    let m = seg.match(/^(.+?):\s*(\d+)\s*$/);
    if (m) { parsed.push({ producto: m[1].trim(), cantidad: Number(m[2]) }); return; }
    m = seg.match(/^(\d+)\s+(.+)$/);
    if (m) { parsed.push({ producto: m[2].trim(), cantidad: Number(m[1]) }); return; }
  });
}
if (!parsed || !parsed.length) {
  return 'No pude leer los productos. Pasá un JSON como [{"producto":"Sandalias Delgadas","cantidad":100},{"producto":"Cilindros","cantidad":50}].';
}

const { lines, unknown } = orderFromItems(parsed);
if (!lines.length) {
  return 'No reconocí ningún producto válido' + (unknown.length ? ' (desconocidos: ' + unknown.join(", ") + ')' : '') + '. Usá los nombres exactos del catálogo.';
}

// minimums (defense in depth — el agente ya debería validar antes)
const viol = lines.filter(l => typeof MIN_BY_PRODUCT[l.product] === "number" && l.quantity < MIN_BY_PRODUCT[l.product])
  .map(l => l.product + ": pediste " + l.quantity + " (mínimo " + MIN_BY_PRODUCT[l.product] + ")");
if (viol.length) {
  return "MÍNIMO NO ALCANZADO: " + viol.join("; ") + ". Decile al cliente el mínimo real de cada producto y NO cotices hasta que ajuste la cantidad. No calcules envío ni fuerces un cálculo alternativo.";
}

const boxes = packBoxes(lines);
let total = 0;
boxes.forEach(b => { total += costoPorPeso(Number(b.peso.toFixed(2))); });

// NO mencionar nº de cajas ni peso (Regla 2 del prompt: nunca menciones cajas/kg).
return "Costo de envío: $" + total + ". IMPORTANTE: usá $" + total +
  " tal cual en la línea 'Envío:', sumalo a la suma de productos para el Total, y el Anticipo es 50% de ese Total con envío.";

// Convierte el binario de Telegram en data URL (OpenAI Vision acepta base64).
// En producción (GHL) no hay binario y se conserva el media_url original.
const base = $('Combine Messages').first().json;
const item = $input.first();
let media_url = base.media_url || '';
try {
  if (item.binary && item.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    const mime = item.binary.data.mimeType || (base.message_type === 'audio' ? 'audio/ogg' : 'image/jpeg');
    media_url = `data:${mime};base64,${buf.toString('base64')}`;
  }
} catch (e) {}
return [{ json: { ...base, media_url }, binary: item.binary }];

// Telegram Trigger -> shape base para la cadena de resolucion de CRM.
// NO inventa ids de GHL: contact_id y opportunity_id los resuelve la cadena "GHL: ..." aguas abajo.
// La unica diferencia con produccion (WhatsApp/GHL) es el canal: aca la identidad del lead
// se ancla al chat de Telegram via un email deterministico.
return $input.all().map(item => {
  const j    = item.json || {};
  const msg  = j.message || j;
  const chat = msg.chat || {};
  const from = msg.from || {};

  const chatId = String(chat.id ?? from.id ?? '');
  if (!chatId) throw new Error('Update de Telegram sin chat.id');

  let message_type     = 'text';
  let message_text     = msg.text || msg.caption || '';
  let telegram_file_id = '';

  if (msg.voice || msg.audio) {
    message_type = 'audio';
    telegram_file_id = (msg.voice || msg.audio).file_id || '';
  } else if (Array.isArray(msg.photo) && msg.photo.length) {
    message_type = 'image';
    telegram_file_id = msg.photo[msg.photo.length - 1].file_id || '';
  } else if (!message_text) {
    // sticker / gif / documento / video / ubicacion / contacto: no los podemos leer,
    // pero NO deben tirar la ejecucion. El agente responde con naturalidad.
    message_type = 'text';
    message_text = '(el lead mando un sticker o archivo que no puedo abrir)';
  }

  // /start de Telegram = "el lead abrio el chat" -> equivale a un saludo, no a un comando.
  const raw = String(message_text).trim().toLowerCase();
  if (raw === '/start') message_text = 'hola';

  const RESET = ['/b', '/borrar', '/reset', '/clear'];
  const is_command = RESET.includes(raw);

  const first_name = from.first_name || chat.first_name || '';
  const last_name  = from.last_name  || chat.last_name  || '';
  const full_name  = [first_name, last_name].filter(Boolean).join(' ') || ('Telegram ' + chatId);

  return {
    json: {
      source: 'telegram',
      channel: 'telegram',
      telegram_chat_id: chatId,
      session_key: 'tg_' + chatId,
      first_name,
      last_name,
      full_name,
      // Email deterministico: es la llave de dedup del upsert de GHL (Telegram no da telefono).
      email_sintetico: 'tg-' + chatId + '@telegram.[TU-DOMINIO]',
      message_type,
      message_text,
      media_url: '',
      media_type: '',
      telegram_file_id,
      is_command,
    },
  };
});

// Resuelve el contexto real de GHL para un chat de Telegram.
// Equivale a lo que en produccion trae el webhook de WF-01: contact_id, opportunity_id,
// stage (nombre) y custom_fields (por key). Ademas construye los mapas de stage ids y
// custom field ids, que en produccion viven hardcodeados.
const LOCATION_ID   = 'onRwi0ZF4uYi0Lp6GAbE';
const PIPELINE_NAME = 'Happy Flops IA';

const grab = (node) => { try { return $(node).first().json || {}; } catch (e) { return {}; } };

// ─────────── contacto ───────────
const up = grab('GHL: Upsert Contacto');
const contact = up.contact || up.data || up || {};
const contact_id = String(contact.id || '');
const contact_tags = (contact.tags || []).map(t => String(t).trim().toLowerCase());

// ─────────── pipeline + stages ───────────
const pipesRaw = grab('GHL: Pipelines');
const pipelines = pipesRaw.pipelines || pipesRaw.data || [];
const pipe =
  pipelines.find(p => String(p.name || '').trim().toLowerCase() === PIPELINE_NAME.toLowerCase()) ||
  pipelines[0] || null;

const STAGE_ID_BY_NAME = {};
const STAGE_NAME_BY_ID = {};
for (const s of (pipe && pipe.stages) || []) {
  STAGE_ID_BY_NAME[String(s.name).trim()] = s.id;
  STAGE_NAME_BY_ID[s.id] = String(s.name).trim();
}
// Fallback: ids conocidos por hardcode historico (sirven si el GET de pipelines falla).
const STAGE_FALLBACK = {
  'Cotizado':        '96fa0ade-c853-4db3-97f4-56d58d69af8c',
  'Esperando Pago':  '843a06f1-1214-4baa-a3a0-f197cb240b5d',
  'Pago Confirmado': '96d760e5-f290-456c-a117-57e61ce6c27d',
};
for (const [k, v] of Object.entries(STAGE_FALLBACK)) {
  if (!STAGE_ID_BY_NAME[k]) { STAGE_ID_BY_NAME[k] = v; STAGE_NAME_BY_ID[v] = k; }
}

// ─────────── definiciones de custom fields ───────────
const cfRaw  = grab('GHL: Custom Fields Opp');
const cfDefs = cfRaw.customFields || cfRaw.data || [];
const CF_ID_BY_KEY = {};
const CF_KEY_BY_ID = {};
for (const f of cfDefs) {
  const key = String(f.fieldKey || f.key || '').replace(/^opportunity\./, '').replace(/^contact\./, '');
  if (!key || !f.id) continue;
  CF_ID_BY_KEY[key] = f.id;
  CF_KEY_BY_ID[f.id] = key;
}
// El unico id conocido por hardcode historico.
if (!CF_KEY_BY_ID['ahVpF5ldsRcuOIn9Mxdk']) {
  CF_KEY_BY_ID['ahVpF5ldsRcuOIn9Mxdk'] = 'evento_detectado';
  CF_ID_BY_KEY['evento_detectado'] = CF_ID_BY_KEY['evento_detectado'] || 'ahVpF5ldsRcuOIn9Mxdk';
}

// customFields de un opportunity -> objeto plano por key
function cfObject(opp) {
  const out = {};
  for (const cf of (opp && opp.customFields) || []) {
    const key = CF_KEY_BY_ID[cf.id] || String(cf.key || cf.fieldKey || '').replace(/^opportunity\./, '');
    if (!key) continue;
    let v = cf.fieldValue !== undefined ? cf.fieldValue
          : cf.field_value !== undefined ? cf.field_value
          : cf.value;
    if (Array.isArray(v)) v = v[0];
    out[key] = v;
  }
  return out;
}

// ─────────── oportunidad ───────────
const searchRaw = grab('GHL: Buscar Oportunidad');
// distinguir "la busqueda respondio vacio" de "la busqueda fallo": si falla y lo tomamos
// como lista vacia, creariamos una oportunidad nueva en CADA mensaje.
const searchOk = Array.isArray(searchRaw.opportunities) || Array.isArray(searchRaw.data);
let opps = searchRaw.opportunities || searchRaw.data || [];
if (!Array.isArray(opps)) opps = [];
if (pipe) {
  const delPipe = opps.filter(o => String(o.pipelineId || '') === String(pipe.id));
  if (delPipe.length) opps = delPipe;
}
// preferimos la abierta mas reciente
opps.sort((a, b) => {
  const ao = (a.status === 'open') ? 1 : 0;
  const bo = (b.status === 'open') ? 1 : 0;
  if (ao !== bo) return bo - ao;
  return String(b.updatedAt || b.dateUpdated || '').localeCompare(String(a.updatedAt || a.dateUpdated || ''));
});
const opp = opps[0] || null;

const stageName = opp
  ? (STAGE_NAME_BY_ID[opp.pipelineStageId] || String(opp.pipelineStageName || '').trim() || 'Lead Nuevo')
  : 'Lead Nuevo';

const base = $('Normalizar Telegram').first().json;

return {
  ...base,
  crm_ok: !!contact_id,
  location_id: LOCATION_ID,
  pipeline_id: pipe ? pipe.id : '',
  pipeline_name: pipe ? pipe.name : '',
  contact_id,
  contact_tags,
  opportunity_id: opp ? opp.id : '',
  // solo creamos oportunidad si la busqueda REALMENTE respondio y vino vacia
  needs_opportunity: !opp && searchOk,
  search_ok: searchOk,
  stage: stageName,
  custom_fields: cfObject(opp),
  stage_ids: STAGE_ID_BY_NAME,
  stage_names: STAGE_NAME_BY_ID,
  cf_ids: CF_ID_BY_KEY,
  cf_keys: CF_KEY_BY_ID,
  _diag: {
    pipelines_encontrados: pipelines.length,
    cf_defs_encontradas: cfDefs.length,
    opps_encontradas: opps.length,
  },
};

// Maquina de estados del pipeline (lo que en produccion hace WF-06 dentro de GHL).
// Regla: solo AVANZA, nunca retrocede. La disparan los custom fields que escribieron las tools.
//   evento_detectado      -> Evento Identificado
//   productos_mostrados   -> Productos Mostrados
//   cotizacion_emitida    -> Cotizado   (COTIZADOR ya lo mueve por su cuenta; esto es la red)
const j   = $json;
const cf  = j.cf_despues || {};
const ids = j.stage_ids || {};

const ORDEN = [
  'Lead Nuevo', 'Saludo Enviado', 'Evento Identificado', 'Productos Mostrados', 'Cotizado',
  'Esperando Pago', 'Pago Confirmado', 'Diseño en Proceso', 'En Producción', 'Enviado',
];
const idx = (s) => { const i = ORDEN.indexOf(s); return i === -1 ? -1 : i; };

const actual = j.stage_actual_crm || j.stage || 'Lead Nuevo';
let destino = actual;

const truthy = (v) => v === true || v === 'true' || v === 1 || v === '1' || (typeof v === 'string' && v.trim() !== '' && v.trim().toLowerCase() !== 'false');

const subir = (nombre) => {
  if (idx(nombre) > idx(destino)) destino = nombre;
};

if (String(cf.evento_detectado || '').trim()) subir('Evento Identificado');
if (String(cf.productos_mostrados || '').trim()) subir('Productos Mostrados');
if (truthy(cf.cotizacion_emitida)) subir('Cotizado');

// Fuera del pipeline lineal (En Espera, Ganado, Ventas Perdidas) no tocamos nada.
const fueraDeLinea = idx(actual) === -1;
const mover = !fueraDeLinea && destino !== actual && !!ids[destino];

return {
  ...j,
  stage_destino: destino,
  stage_destino_id: ids[destino] || '',
  mover_stage: mover,
};

const antes = ($('Auth + Normalize').first().json.contact_tags || []).map(t => String(t).toLowerCase());
const c = ($json.contact || $json || {});
const ahora = (c.tags || []).map(t => String(t).toLowerCase());
const nueva = ahora.includes('atencion_humana') && !antes.includes('atencion_humana');
return { ...$('Auth + Normalize').first().json, atencion_nueva: nueva, tags_ahora: ahora };

